function law(){
var q=normalizeLawSearch((($("#qlaw")||{}).value||"").trim()),tokens=q.split(/\s+/).filter(Boolean),list=laws.filter(function(x){var text=normalizeLawSearch([x.id,x.article,x.category,x.title,x.description,x.bailNote].join(" "));return(cat==="Todas"||x.category===cat)&&tokens.every(function(term){return text.includes(term)})}),chosen=laws.filter(function(x){return sel.includes(x.id)}),reduction=Math.min(att.reduce(function(sum,id){return sum+({primario:30,advogado:20,confesso:10,comportamento:10}[id]||0)},0),40)/100,baseMonths=0,baseFine=0,bailTotal=0,bailRestricted=false;
function exclusion(x){if(sel.includes("25")&&["31","37"].includes(x.id))return"Art. "+x.id+" não soma com Art. 25.";if(sel.includes("26")&&["35","36"].includes(x.id))return"Art. "+x.id+" não soma com Art. 26.";if((sel.includes("50")||sel.includes("51"))&&x.id==="37")return"Art. 37 não soma com Art. 50 ou 51.";if((sel.includes("50")||sel.includes("51"))&&x.id==="35"&&!overrides.includes("ammo"))return"Com Art. 50/51, só soma fora da regra de munição 9 mm até 10 unidades.";if((sel.includes("50")||sel.includes("51"))&&x.id==="36"&&!overrides.includes("weapon"))return"Com Art. 50/51, só soma fora da regra de até 2 armas Colt.";return""}
var included=chosen.filter(function(x){return!exclusion(x)});included.forEach(function(x){baseMonths+=x[mode?"max":"min"];baseFine+=x.fine;if(x.bail==null)bailRestricted=true;else bailTotal+=x.bail});
var totalMonths=baseMonths*(1-reduction),fineTotal=Math.round(baseFine*(1-reduction)),hasHome=chosen.some(function(x){return x.id==="50"||x.id==="51"}),needAmmo=hasHome&&chosen.some(function(x){return x.id==="35"}),needWeapon=hasHome&&chosen.some(function(x){return x.id==="36"}),act="<div class='law-actions'><button data-a='penal-table'>▦ Tabela de fianças e multas</button><button data-r='regras-roubo'>⚑ Regras de Roubo</button></div>";
var filters=cats.map(function(c){var n=c==="Todas"?laws.length:laws.filter(function(x){return x.category===c}).length;return"<button class='"+(cat===c?"selected":"")+"' data-a='cat' data-v='"+esc(c)+"'>"+esc(c)+" <small>"+n+"</small></button>"}).join("");
var cards=list.map(function(x){var chosenNow=sel.includes(x.id);return"<article class='penal-item "+(chosenNow?"is-selected":"")+"'><div class='penal-item-top'><span class='tag'>"+esc(x.article)+"</span><span class='penal-category'>"+esc(x.category)+"</span></div><h3>"+esc(x.title)+"</h3><p>"+esc(x.description)+"</p><div class='penal-facts'><span class='penal-sentence'><small>Pena em meses</small><b>"+x.min+(x.min===x.max?"":"–"+x.max)+" meses</b></span><span><small>Multa — redução</small><b>"+money(x.fine)+"</b></span><span><small>Fiança</small><b>"+(x.bail==null?esc(x.bailNote):money(x.bail))+"</b></span></div><button class='penal-select' data-a='penal-toggle' data-id='"+esc(x.id)+"'>"+(chosenNow?"✓ Remover da soma":"＋ Adicionar à soma")+"</button></article>"}).join("")||"<div class='empty penal-empty'>Nenhum artigo encontrado.</div>";
var selectedRows=chosen.map(function(x){var why=exclusion(x);return"<div class='selectedrow "+(why?"not-summed":"")+"'><span><b>"+esc(x.article)+" · "+esc(x.title)+"</b><strong class='penal-selected-months'>"+(mode?x.max:x.min)+" meses</strong><small>"+(why?esc(why):"Incluída no total")+"</small></span><button aria-label='Remover "+esc(x.title)+"' data-a='penal-toggle' data-id='"+esc(x.id)+"'>×</button></div>"}).join("")||"<p class='hint'>Adicione artigos para calcular a pena.</p>";
var reductions=[["primario","Réu primário","−30%"],["advogado","Advogado presente","−20%*"],["confesso","Réu confesso","−10%"],["comportamento","Bom comportamento","−10%"]].map(function(x){return"<label class='penal-check'><span>"+x[1]+" <b>"+x[2]+"</b></span><input type='checkbox' data-att='"+x[0]+"' "+(att.includes(x[0])?"checked":"")+"></label>"}).join("");
var overrideRows=(needAmmo?"<label class='penal-check exception-check'><span>Confirmo que a munição não é 9 mm ou passa de 10 unidades; permitir somar o Art. 35.</span><input type='checkbox' data-override='ammo' "+(overrides.includes("ammo")?"checked":"")+"></label>":"")+(needWeapon?"<label class='penal-check exception-check'><span>Confirmo que a arma não é Colt ou são mais de 2 armas; permitir somar o Art. 36.</span><input type='checkbox' data-override='weapon' "+(overrides.includes("weapon")?"checked":"")+"></label>":"");
return head("LEGACY ROLEPLAY · ROTA","Código Penal — Calculadora RP","Consulte os 52 artigos e 56 enquadramentos. Selecione os itens para somar a pena, multa e fiança.",act)+"<div class='penal-notice'>Tabela demonstrativa do servidor. As penas são expressas em meses. Aplicam-se as regras de não-somatória descritas na página Regras de Roubo.</div><div class='penal-layout'><section class='penal-catalog'><div class='penal-toolbar'><input id='qlaw' data-search placeholder='Buscar artigo, crime ou descrição...' value='"+esc(q)+"'><span>"+list.length+" resultado(s)</span></div><div class='penal-filters'>"+filters+"</div><div class='penal-grid'>"+cards+"</div></section><aside class='panel penal-calculator'><div class='panelhead'><div><small class='kicker'>DOSIMETRIA DE ROLEPLAY</small><h2>Cálculo da pena</h2></div><span>"+chosen.length+" selecionado(s)</span></div><div class='penal-mode'><span>Modo de pena</span><div><button data-a='mode' data-v='0' class='"+(!mode?"selected":"")+"'>Mínima</button><button data-a='mode' data-v='1' class='"+(mode?"selected":"")+"'>Máxima</button></div></div><div class='penal-reductions'><div class='penal-subhead'>Atenuantes <small>limite combinado: 40%</small></div>"+reductions+"<p class='hint'>* Aplique apenas conforme as regras do servidor.</p></div>"+(overrideRows?"<div class='penal-reductions'><div class='penal-subhead'>Exceções da regra de roubo</div>"+overrideRows+"</div>":"")+"<div class='penal-subhead'>Artigos selecionados</div><div class='penal-selected'>"+selectedRows+"</div><div class='penal-totals'><div class='penal-total-sentence'><span>Pena total</span><b>"+totalMonths.toLocaleString("pt-BR",{maximumFractionDigits:1})+" meses</b><small>Modo "+(mode?"máximo":"mínimo")+(reduction?" · redução "+Math.round(reduction*100)+"%":"")+"</small></div><div><span>Multa — redução</span><b>"+money(fineTotal)+"</b></div><div><span>Fiança total</span><b>"+money(bailTotal)+(bailRestricted?" + análise de delegado":"")+"</b></div></div><button class='penal-clear' data-a='penal-clear' "+(chosen.length?"":"disabled")+">Limpar cálculo</button></aside></div><p class='hint penal-disclaimer'>Conteúdo fictício para roleplay no MTA. Não é orientação jurídica, tabela oficial ou cálculo de pena real.</p>"
}
function robberyRules(){return head("PROCEDIMENTO OPERACIONAL · ROTA","Regras de Roubo","Exceções de não-somatória e condições especiais para o cálculo RP.","<button data-r='regras'>← Voltar ao Código Penal</button>")+"<div class='penal-notice'>Durante a execução do roubo, alguns artigos são absorvidos pela tipificação principal. Quando a regra permite exceção, marque a condição confirmada na calculadora para incluir o artigo secundário.</div><div class='robbery-rules-grid'><article class='robbery-rule-card'><span class='tag'>ART. 25</span><h2>Roubo à Caixinha / Caixa Eletrônico</h2><div class='robbery-exclusion'><b>Art. 31º — Posse de Dinheiro Sujo</b><p>Não pode ser somado quando decorre do mesmo roubo à Caixinha.</p></div><div class='robbery-exclusion'><b>Art. 37º — Tentativa de Fuga</b><p>Não pode ser somada durante a ação do roubo à Caixinha.</p></div></article><article class='robbery-rule-card'><span class='tag'>ART. 26</span><h2>Roubo a Estabelecimento</h2><div class='robbery-exclusion'><b>Art. 35º — Posse de Munição Ilegal</b><p>Não pode ser somada durante a ação de roubo ao estabelecimento.</p></div><div class='robbery-exclusion'><b>Art. 36º — Posse Ilegal de Armamento de Fogo</b><p>Não pode ser somada durante a ação de roubo ao estabelecimento.</p></div></article><article class='robbery-rule-card'><span class='tag'>ART. 50</span><h2>Invasão a Domicílio / Roubo a Residência</h2><div class='robbery-exclusion conditional'><b>Art. 35º — Posse de Munição Ilegal</b><p>Não soma para munição 9 mm até 10 unidades. Se for outro calibre ou mais de 10 unidades, pode somar.</p></div><div class='robbery-exclusion conditional'><b>Art. 36º — Posse Ilegal de Armamento de Fogo</b><p>Não soma para Colt até 2 armas. Se for outro armamento ou mais de 2 armas, pode somar.</p></div><div class='robbery-exclusion'><b>Art. 37º — Tentativa de Fuga</b><p>Não pode ser somada na ação de roubo a residências.</p></div></article><article class='robbery-rule-card'><span class='tag'>ART. 51</span><h2>Roubo a Covas</h2><div class='robbery-exclusion conditional'><b>Art. 35º — Posse de Munição Ilegal</b><p>Não soma para munição 9 mm até 10 unidades. Se for outro calibre ou mais de 10 unidades, pode somar.</p></div><div class='robbery-exclusion conditional'><b>Art. 36º — Posse Ilegal de Armamento de Fogo</b><p>Não soma para Colt até 2 armas. Se for outro armamento ou mais de 2 armas, pode somar.</p></div><div class='robbery-exclusion'><b>Art. 37º — Tentativa de Fuga</b><p>Não pode ser somada na ação de roubo a covas.</p></div></article></div><div class='robbery-note'><b>Observação</b><p>Outros artigos não listados nestas exceções podem ser somados se a infração correspondente tiver ocorrido durante a cena. Registre apenas fatos confirmados no RP.</p></div>"}
function openPenaltyTable(){var m=$("#modal");m.innerHTML="<div class='modalhead'><h2>Tabela de fianças e multas · ROTA RP</h2><button type='button' data-a='close'>×</button></div><div class='penal-table-wrap'><table class='penal-table'><thead><tr><th>Artigo</th><th>Crime</th><th>Pena</th><th>Multa — redução</th><th>Fiança</th></tr></thead><tbody>"+laws.map(function(x){return"<tr><td>"+esc(x.article)+"</td><td><b>"+esc(x.title)+"</b><small>"+esc(x.category)+"</small></td><td>"+x.min+(x.min===x.max?"":"–"+x.max)+" meses</td><td>"+money(x.fine)+"</td><td>"+(x.bail==null?esc(x.bailNote):money(x.bail))+"</td></tr>"}).join("")+"</tbody></table></div><div class='penal-table-footer'><small>Portal fictício de roleplay. Valores reproduzem a tabela informada e a página de referência.</small><button class='primary' data-a='close'>Fechar tabela</button></div>";m.showModal()}
function recruitment(){
var selected=(data.editais||[]).find(function(x){return x.id===selectedEditalId});
var questions=[
{number:'1',name:'characterName',title:'Qual o nome completo do seu personagem?',kind:'input',placeholder:'Nome e sobrenome do personagem'},
{number:'2',name:'characterId',title:'Qual o ID do seu personagem?',kind:'input',placeholder:'ID / passaporte usado no servidor'},
{number:'3',name:'realAge',title:'Quantos anos você tem (vida real)?',kind:'age',placeholder:'Sua idade'},
{number:'4',name:'rpExperience',title:'Há quanto tempo você participa de servidores Roleplay?',placeholder:'Conte há quanto tempo joga RP e, se quiser, em quais tipos de servidor.'},
{number:'5',name:'policeExperience',title:'Você já participou de alguma corporação policial? Se sim, qual foi sua trajetória?',placeholder:'Se nunca participou, escreva: Nunca participei.'},
{number:'6',name:'roleplayDefinition',title:'O que significa Roleplay para você?',placeholder:'Explique com suas palavras o que é interpretar um personagem.'},
{number:'7',name:'metagamingDefinition',title:'Explique com suas palavras o que é Meta Gaming (MG) e por que essa prática é proibida.',placeholder:'Descreva o que é MG e como ele prejudica o roleplay.'},
{number:'8',name:'powergamingDefinition',title:'Explique com suas palavras o que é Power Gaming (PG) e por que essa prática é proibida.',placeholder:'Descreva o que é PG e como ele prejudica o roleplay.'},
{number:'9',name:'whyPmce',title:'Por que você deseja ingressar na ROTA e o que acredita poder agregar à corporação?',placeholder:'Conte suas motivações e como pretende contribuir com a unidade.'},
{number:'10',name:'characterStory',title:'Conte a história completa do seu personagem.',placeholder:'Apresente a trajetória, personalidade, objetivos e acontecimentos importantes do personagem.'}
];
var questionFields=questions.map(function(q){var control=q.kind==='input'?"<input id='apply-"+q.name+"' name='"+q.name+"' required maxlength='"+(q.number==='2'?'40':'100')+"' autocomplete='off' placeholder='"+q.placeholder+"'>":q.kind==='age'?"<input id='apply-"+q.name+"' name='"+q.name+"' type='number' required min='1' max='120' step='1' inputmode='numeric' placeholder='"+q.placeholder+"'>":"<textarea id='apply-"+q.name+"' name='"+q.name+"' required minlength='"+(q.number==='4'||q.number==='5'?'2':q.number==='10'?'10':'5')+"' maxlength='"+(q.number==='10'?'4000':q.number==='5'?'1200':q.number==='4'?'500':'1500')+"' rows='4' placeholder='"+q.placeholder+"'></textarea>";return "<div class='application-question application-question-"+q.number+"'><label for='apply-"+q.name+"'><span>QUESTÃO "+q.number+"</span><b>"+q.title+" <i aria-hidden='true'>*</i></b></label>"+control+"</div>"}).join('');
return head("INGRESSO NA UNIDADE","Ficha de recrutamento","Preencha a ficha completa para participar do processo seletivo da ROTA.","<button data-r='editais'>← Voltar aos editais</button>")+(selected?"<div class='recruitment-selected'><small>EDITAL SELECIONADO</small><b>"+esc(selected.title)+"</b><span>Encerramento: "+formatEditalDate(selected.closesAt)+"</span></div>":"")+"<div class='application-layout'><section class='panel form-panel application-panel'><div class='panelhead'><div><small class='kicker'>PROCESSO SELETIVO · ROTA</small><h2>Ficha de recrutamento</h2></div><span class='application-required'>* obrigatório</span></div><form id='apply' class='form application-form'><input type='hidden' name='editalId' value='"+esc(selected?selected.id:"")+"'><section class='application-section'><div class='application-section-heading'><span>01</span><div><h3>Identificação</h3><p>Informe seus dados e a identificação usada no servidor.</p></div></div><div class='application-personal-grid'><label for='apply-fullName'>Nome completo <i aria-hidden='true'>*</i><input id='apply-fullName' name='fullName' required minlength='2' maxlength='100' autocomplete='name' placeholder='Seu nome completo'></label><label for='apply-serverRg'>RG no servidor <i aria-hidden='true'>*</i><input id='apply-serverRg' name='serverRg' required maxlength='60' autocomplete='off' placeholder='RG cadastrado no servidor'></label></div></section><section class='application-section'><div class='application-section-heading'><span>02</span><div><h3>Questionário do processo seletivo</h3><p>Responda com atenção. Todas as perguntas são obrigatórias.</p></div></div><div class='application-questionnaire'>"+questionFields+"</div></section><div class='application-notice full'><b>Antes de enviar</b><span>A inscrição não exige login. Após enviar, o mesmo ID de personagem só poderá realizar outra inscrição depois de 48 horas.</span></div><div class='apply-feedback full' data-apply-feedback aria-live='polite'></div><button class='primary application-submit full' type='submit'>Enviar ficha de recrutamento <span aria-hidden='true'>→</span></button></form></section><aside class='panel application-aside'><div class='application-aside-mark' aria-hidden='true'>ROTA<span>SELEÇÃO</span></div><small class='kicker'>COMO FUNCIONA</small><h2>Uma etapa de cada vez.</h2><div class='rows'><div class='recruitment-step'><b>01</b><span>Leia o edital<small>Confira requisitos e prazo de inscrição.</small></span></div><div class='recruitment-step'><b>02</b><span>Envie sua ficha<small>Responda às perguntas com sinceridade.</small></span></div><div class='recruitment-step'><b>03</b><span>Aguarde a análise<small>A equipe da ROTA avaliará sua candidatura.</small></span></div></div><p class='hint'>As respostas ficam disponíveis para análise da administração da ROTA.</p></aside></div>"}

function access(){
var active=['police','request','admin'].indexOf(accessTab)!==-1?accessTab:'police',tabs=[['police','Login policial'],['request','Solicitar token'],['admin','Administrador']],forms={
police:"<form id='access'><input type='hidden' name='mode' value='police'><label class='field'>Nome aprovado pela administração<input name='name' required minlength='2' maxlength='60' autocomplete='username' placeholder='Seu nome ou QRA na ROTA'></label><label class='field'>Token pessoal<input type='password' name='token' required minlength='12' maxlength='100' autocomplete='current-password' placeholder='Cole o token aprovado pelo comando'></label><button class='primary access-submit'>Entrar como policial <span aria-hidden='true'>→</span></button><p class='hint'>O acesso policial usa um token pessoal emitido após aprovação da administração.</p></form>",
request:"<form id='access'><input type='hidden' name='mode' value='request'><label class='field'>Nome completo ou QRA<input name='name' required minlength='2' maxlength='60' autocomplete='name' placeholder='Como a administração identifica você'></label><label class='field'>Tipo do pedido<select name='requestType' required><option value='acesso'>Primeiro acesso à conta policial</option><option value='troca_token'>Preciso trocar meu token</option></select></label><button class='primary access-submit'>Solicitar token <span aria-hidden='true'>→</span></button><div class='access-approval-note'><b>Seu pedido será analisado</b><span>O token só é gerado quando um administrador aprovar a solicitação.</span></div></form>",
admin:"<form id='access'><input type='hidden' name='mode' value='admin'><label class='field'>Usuário administrador<input name='username' required autocomplete='username' placeholder='Usuário configurado pelo administrador'></label><label class='field'>Senha administrativa<input type='password' name='password' required autocomplete='current-password' placeholder='Sua senha de administração'></label><button class='primary access-submit'>Entrar na administração <span aria-hidden='true'>→</span></button><p class='hint'>O perfil administrativo é separado do acesso policial e tem permissões de gestão.</p></form>"};
return "<div class='login access-login'><aside class='access-identity'><div class='access-crest-wrap'><img src='assets/brasao-rota.png' alt='Brasão da ROTA'></div><span class='kicker'>PORTAL OPERACIONAL · LEGACY ROLEPLAY</span><h2>Acesso da ROTA</h2><p>Uma entrada organizada para quem serve na unidade e para quem administra o portal.</p><div class='access-identity-list'><span><i>01</i><b>Solicite seu token</b><small>A administração revisa cada pedido.</small></span><span><i>02</i><b>Acesse como policial</b><small>Use seu nome aprovado e token individual.</small></span><span><i>03</i><b>Gestão administrativa</b><small>O administrador entra pelo acesso próprio.</small></span></div><div class='access-identity-foot'><span class='access-live-dot'></span> AUTENTICAÇÃO PELO SERVIDOR</div></aside><section class='loginform access-panel'><div class='access-panel-heading'><span class='kicker'>ÁREA RESTRITA</span><h1>Portal da equipe</h1><p>Escolha seu perfil para continuar com segurança.</p></div><div class='access-tabs' role='tablist' aria-label='Tipo de acesso'>"+tabs.map(function(x){return "<button type='button' role='tab' aria-selected='"+(active===x[0])+"' class='"+(active===x[0]?'active':'')+"' data-a='auth-tab' data-v='"+x[0]+"'>"+x[1]+"</button>"}).join('')+"</div>"+forms[active]+(loginMessage?"<p class='notice access-feedback' aria-live='polite'>"+esc(loginMessage)+"</p>":"")+"<div class='access-panel-foot'><span>◆</span> Ambiente fictício para roleplay · acesso protegido</div></section></div>"
}
